using System;

public class IDelayProviderTests
{
[Fact]
public async Task DelayAsync_WithPositiveMilliseconds_ShouldDelayForSpecifiedTime()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var delay = 100; // 100 milliseconds
    var startTime = DateTime.UtcNow;

    // Act
    await delayProvider.DelayAsync(delay);
    var elapsedTime = DateTime.UtcNow - startTime;

    // Assert
    Assert.True(elapsedTime.TotalMilliseconds >= delay, 
        $"Delay should be at least {delay}ms, but was {elapsedTime.TotalMilliseconds}ms");

[Fact]
public async Task DelayAsync_CanceledDuringDelay_ThrowsTaskCanceledException()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cts = new CancellationTokenSource();
    var delayTask = delayProvider.DelayAsync(1000, cts.Token);

    // Act
    cts.Cancel();

    // Assert
    await Assert.ThrowsAsync<TaskCanceledException>(() => delayTask);

[Fact]
public async Task DelayAsync_WithDefaultCancellationToken_ShouldDelayForSpecifiedTime()
{
    // Arrange
    var delayProvider = new DelayProvider();
    int delayMilliseconds = 100;
    var stopwatch = new System.Diagnostics.Stopwatch();

    // Act
    stopwatch.Start();
    await delayProvider.DelayAsync(delayMilliseconds);
    stopwatch.Stop();

    // Assert
    Assert.True(stopwatch.ElapsedMilliseconds >= delayMilliseconds, 
        $"Delay should be at least {delayMilliseconds}ms, but was {stopwatch.ElapsedMilliseconds}ms");
}
